-- Flow-start statistics; prepare using the owned migration runner.
CREATE TABLE IF NOT EXISTS flow_start_statistics_state(id bigint unsigned NOT NULL,legacy_upper_id bigint unsigned NOT NULL,legacy_after_id bigint unsigned NOT NULL,legacy_expected_rows bigint unsigned NOT NULL,legacy_projected_rows bigint unsigned NOT NULL,projected_head bigint unsigned NOT NULL,revision bigint unsigned NOT NULL,created_at datetime(3) NOT NULL,updated_at datetime(3) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS flow_start_statistics_pending(source_id bigint unsigned NOT NULL,subscription_id bigint unsigned NOT NULL,node_id bigint unsigned NOT NULL,occurred_at datetime(3) NOT NULL,received_at datetime(3) NOT NULL,created_at datetime(3) NOT NULL,PRIMARY KEY(source_id),KEY idx_flow_stats_pending_received(subscription_id,received_at,source_id),KEY idx_flow_stats_pending_occurred(subscription_id,occurred_at,source_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS flow_start_statistics_points(source_id bigint unsigned NOT NULL,subscription_id bigint unsigned NOT NULL,node_id bigint unsigned NOT NULL,occurred_at datetime(3) NOT NULL,received_at datetime(3) NOT NULL,source_created_at datetime(3) NOT NULL,review_at datetime(3) NOT NULL,fact_sha256 char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,PRIMARY KEY(source_id),KEY idx_flow_stats_point_retention(review_at,source_id),KEY idx_flow_stats_point_received(subscription_id,received_at,node_id,source_id),KEY idx_flow_stats_point_occurred(subscription_id,occurred_at,node_id,source_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS flow_start_statistics_minutes(subscription_id bigint unsigned NOT NULL,node_id bigint unsigned NOT NULL,basis varchar(16) NOT NULL,minute_at datetime(3) NOT NULL,event_count bigint unsigned NOT NULL,PRIMARY KEY(subscription_id,node_id,basis,minute_at),KEY idx_flow_stats_minute_read(subscription_id,basis,minute_at,node_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

